alter table public.paises enable trigger auditar;
alter table public.estados enable trigger auditar;
alter table public.cidades enable trigger auditar;
select setval(pg_get_serial_sequence('public.paises', 'id'), coalesce((select max(id) from public.paises), 0) + 1, false);
select setval(pg_get_serial_sequence('public.estados', 'id'), coalesce((select max(id) from public.estados), 0) + 1, false);
select setval(pg_get_serial_sequence('public.cidades', 'id'), coalesce((select max(id) from public.cidades), 0) + 1, false);
commit;
